function generate(rand, size) {
  const pool = ['hello', 'world', 'of', 'sql', 'the', 'quick', 'brown', 'fox', 'data', 'science', 'and', 'a', 'i', 'top', 'rated', 'books', 'x', 'machine', 'learning'];
  const pick = list => list[Math.floor(rand() * list.length)];
  // Words come lowercase, uppercase, already capitalized or in random mixed case.
  const casing = word => {
    const r = rand();
    if (r < 0.35) return word;
    if (r < 0.55) return word.toUpperCase();
    if (r < 0.7) return word[0].toUpperCase() + word.slice(1);
    return [...word].map(c => (rand() < 0.5 ? c.toUpperCase() : c)).join('');
  };
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const user_content = [];
  let id = 0;
  for (let r = 0; r < rows; r++) {
    id += 1 + Math.floor(rand() * 3);
    const count = 1 + Math.floor(rand() * (size === 'small' ? 5 : 8));
    let text = '';
    for (let w = 0; w < count; w++) {
      if (w) text += rand() < 0.15 ? '  ' : ' ';
      text += casing(pick(pool));
    }
    if (rand() < 0.1) text = ' ' + text;
    if (rand() < 0.1) text += ' ';
    user_content.push([id, text]);
  }
  return [{ user_content }];
}
